const description: { en: string; ja: string } = {"en":"Three tortoise-shell hexagons, one corner up, one above two, each a narrow white line from the next, each with a thick band, a narrow white line, a thin line and a flower lozenge: the top one first, then the lower right and the lower left.","ja":"角を上にした亀甲を三つ、品の字に並べます。隣どうしは細い白線一本分だけ離します。どの亀甲も、太い帯、細い白線、細い線の順に重ね、その内側に花菱を収めます。上、右下、左下の順に作図します。"};

export default construction;
